"use strict";function toggleSidebar(){let e=document.getElementById("sidebar");e.classList.toggle("active"),document.body.classList.toggle("sidebar-open")}document.addEventListener("DOMContentLoaded",function(){let e=document.querySelector(".typed");e&&new Typed(".typed",{strings:e.getAttribute("data-typed-items").split(","),typeSpeed:50,backSpeed:30,backDelay:2e3,loop:!0});let t=document.querySelectorAll(".counter"),r=!1,n=document.querySelector(".counters-section");if(n){let i=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&!r&&(r=!0,t.forEach(e=>{let t=+e.getAttribute("data-target"),r=0,n=Math.ceil(t/100),i=()=>{r<t?(r+=n,e.innerText=r.toLocaleString(),requestAnimationFrame(i)):e.innerText=t.toLocaleString()};i()}),i.unobserve(n))})},{threshold:.3});i.observe(n)}let l=document.querySelector(".resume-container");if(l){let o=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&(l.classList.add("visible"),o.disconnect())})},{threshold:.2});o.observe(l)}let s=document.querySelectorAll(".skill");if(s.length>0){let a=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&e.target.classList.add("in-view")})},{threshold:.3});s.forEach(e=>a.observe(e))}let c=document.querySelectorAll(".sidebar .menu a");c.forEach(e=>{e.addEventListener("click",()=>{document.getElementById("sidebar").classList.remove("active"),document.body.classList.remove("sidebar-open")})})});const pingURL="https://kontaktformular.onrender.com/ping";function pingServer(){fetch("https://kontaktformular.onrender.com/ping").then(()=>console.log("Server gepingt – sollte wach bleiben.")).catch(()=>console.warn("Ping fehlgeschlagen – Server evtl. im Schlaf."))}window.addEventListener("DOMContentLoaded",()=>{pingServer(),setInterval(pingServer,6e5)});